W,H=A4; CW=W-92
NAVY=colors.HexColor('#17324D');TEAL=colors.HexColor('#147D85');INK=colors.HexColor('#263746');MUTED=colors.HexColor('#5A6C7C');PALE=colors.HexColor('#EDF4F7');LINE=colors.HexColor('#D5E2E8');GOLD=colors.HexColor('#B77622');SAND=colors.HexColor('#FFF5E5')
BODY=ParagraphStyle('Body',fontName='MText',fontSize=10.9,leading=15,textColor=INK,spaceAfter=8,allowWidows=0,allowOrphans=0)
SMALL=ParagraphStyle('Small',parent=BODY,fontSize=9,leading=12,textColor=MUTED,spaceAfter=6)
SUB=ParagraphStyle('Sub',parent=BODY,fontName='MBold',fontSize=13,leading=17,textColor=TEAL,spaceBefore=10,spaceAfter=6,keepWithNext=True)
TITLE=ParagraphStyle('Title',parent=BODY,fontName='MBold',fontSize=24,leading=28,textColor=NAVY,spaceAfter=14,keepWithNext=True)
CELL=ParagraphStyle('Cell',parent=BODY,fontSize=9.7,leading=12.7,spaceAfter=0)
HEAD=ParagraphStyle('Head',parent=CELL,fontName='MBold',textColor=colors.white)

def f(text):return re.sub(r'\*\*(.+?)\*\*',r'<b>\1</b>',escape(text))
def P(text,style=BODY):return Paragraph(f(text),style)
story=[];pages=[]
def start(kicker,title):
    if story:story.append(PageBreak())
    pages.append(title)
    story.append(P(kicker.upper(),ParagraphStyle('Kicker',parent=SMALL,fontName='MBold',textColor=TEAL,spaceAfter=7)))
    story.append(P(title,TITLE))
def para(text):story.append(P(text))
def sub(text):story.append(P(text,SUB))
def bullet(items):
    for text in items:story.append(Paragraph('• '+f(text),ParagraphStyle('Bullet',parent=BODY,leftIndent=10,firstLineIndent=-9,spaceAfter=5)))
def box(text,warm=False):
    t=Table([[P(text)]],colWidths=[CW]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),SAND if warm else PALE),('LINEBEFORE',(0,0),(0,-1),3,GOLD if warm else TEAL),('LEFTPADDING',(0,0),(-1,-1),12),('RIGHTPADDING',(0,0),(-1,-1),12),('TOPPADDING',(0,0),(-1,-1),10),('BOTTOMPADDING',(0,0),(-1,-1),4)]));story.extend([t,Spacer(1,9)])
def table(headers,rows,ratios,fontsize=None):
    cs=CELL if fontsize is None else ParagraphStyle('TightCell',parent=CELL,fontSize=fontsize,leading=fontsize*1.31)
    hs=HEAD if fontsize is None else ParagraphStyle('TightHead',parent=cs,fontName='MBold',textColor=colors.white)
    t=Table([[P(x,hs) for x in headers]]+[[P(x,cs) for x in row] for row in rows],colWidths=[CW*r/sum(ratios) for r in ratios],repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),NAVY),('ROWBACKGROUNDS',(0,1),(-1,-1),[PALE,colors.white]),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8),('LINEBELOW',(0,1),(-1,-1),0.4,LINE)]))
    story.extend([t,Spacer(1,9)])

